class Solution {
    public String maximumBinaryString(String binary){
        int first=binary.indexOf('0');
        if(first<0)return binary;
        int zeros=0;
        for(char bit:binary.toCharArray())if(bit=='0')zeros++;
        char[] answer=new char[binary.length()];
        Arrays.fill(answer,'1');
        answer[first+zeros-1]='0';
        return new String(answer);
    }
}

code.kotlin:
class Solution {
    fun maximumBinaryString(binary:String):String{
        val first=binary.indexOf('0');
        if(first<0)return binary;
        val zeros=binary.count{
            it=='0'
        };
        val answer=CharArray(binary.length){
            '1'
        };
        answer[first+zeros-1]='0';
        return String(answer)
    }
}

code.cpp:
class Solution {
    public: string maximumBinaryString(string binary){
        int first=binary.find('0');
        if(first==(int)string::npos)return binary;
        int zeros=count(binary.begin(),binary.end(),'0');
        string answer(binary.size(),'1');
        answer[first+zeros-1]='0';
        return answer;
    }
};
